let selected=['masu','nai','te','ta'],visible=[];const $=id=>document.getElementById(id);const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
function render(){const q=normalize($('search').value.trim());const groups=[...document.querySelectorAll('input[name="verb-group"]:checked')].map(x=>+x.value);visible=verbs.filter(v=>groups.includes(v.group)&&normalize(v.word+' '+v.kana+' '+v.meaning).includes(q));const cols=columns.filter(c=>selected.includes(c[0]));$('thead').innerHTML='<tr><th scope="col">Động từ<small>Thể từ điển · Nghĩa tiếng Việt</small></th>'+cols.map(c=>`<th scope="col" class="explain-header" tabindex="0" data-form="${c[0]}" aria-label="Giải thích thể ${c[1]}"><span class="header-form">${c[1]}</span><small>${c[2]}</small></th>`).join('')+'</tr>';$('tbody').innerHTML=visible.length?visible.map(v=>{const f=conjugate(v),r=conjugate(v,v.kana);return `<tr><td><div class="word-top"><button class="explain-word" data-verb="${v.id}" data-form="dictionary" aria-label="Giải thích thể từ điển của ${v.word}" lang="ja">${v.word}</button><span class="badge g${v.group}">${['','I','II','III'][v.group]}</span></div>${$('reading').checked?`<small lang="ja">${v.kana}</small>`:''}<div class="meaning">${v.meaning}</div></td>`+cols.map(c=>`<td><button class="explain-word" data-verb="${v.id}" data-form="${c[0]}" aria-label="Giải thích cách chia ${f[c[0]]}" lang="ja">${f[c[0]]}</button>${$('reading').checked&&f[c[0]]!==r[c[0]]?`<small lang="ja">${r[c[0]]}</small>`:''}</td>`).join('')+'</tr>'}).join(''):`<tr><td colspan="${cols.length+1}" class="empty">${groups.length?'Không tìm thấy động từ. Thử từ khóa khác hoặc chọn thêm nhóm.':'Hãy chọn ít nhất một nhóm động từ để xem bảng.'}</td></tr>`;$('count').textContent=`Hiển thị ${visible.length} / ${verbs.length} động từ`;$('total').textContent=verbs.length}
$('column-picker').innerHTML=columns.map(c=>`<label><input type="checkbox" value="${c[0]}" ${selected.includes(c[0])?'checked':''}>${c[1]}</label>`).join('');$('column-picker').addEventListener('change',()=>{selected=[...$('column-picker').querySelectorAll('input:checked')].map(x=>x.value);document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('active'));render()});document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.preset==='all'?columns.map(c=>c[0]):b.dataset.preset==='polite'?['masu','masen','mashita','masendeshita','mashou']:['masu','nai','te','ta'];document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));$('column-picker').querySelectorAll('input').forEach(x=>x.checked=selected.includes(x.value));render()}));['search','reading'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('export').onclick=()=>{const cols=columns.filter(c=>selected.includes(c[0]));const rows=[['Động từ','Cách đọc','Nghĩa','Nhóm',...cols.map(c=>c[1])],...visible.map(v=>{let f=conjugate(v);return [v.word,v.kana,v.meaning,v.group,...cols.map(c=>f[c[0]])]})];const csv='\ufeff'+rows.map(row=>row.map(s=>'"'+String(s).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let a=document.createElement('a');a.href=url;a.download='kotoba-dong-tu-n5.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();

const groupInputs=[...document.querySelectorAll('input[name="verb-group"]')];groupInputs.forEach(input=>input.addEventListener('change',()=>{const count=groupInputs.filter(x=>x.checked).length;$('all-groups').checked=count===3;$('all-groups').indeterminate=count>0&&count<3;render()}));$('all-groups').addEventListener('change',()=>{groupInputs.forEach(x=>x.checked=$('all-groups').checked);$('all-groups').indeterminate=false;render()});
